33"},{"n":"Installation system — Ceiling angle","c":"roofing-ceilings--expanded-product-families","p":48000,"u":"sheet","i":1,"s":"S026,S027,S028,S029,S032,S127"},{"n":"Installation system — Roof rafter","c":"roofing-ceilings--expanded-product-families","p":48000,"u":"sheet","i":1,"s":"S026,S027,S028,S029,S032,S033"}]'::jsonb)
    as x(n text, c text, p bigint, u text, i int, s text)
),
pairs as (
  select src.n, src.c, src.p, src.u, src.i, trim(code) as code
  from src, unnest(string_to_array(src.s, ',')) as code
),
ins as (
  insert into products (supplier_id, name, category_id, description, price, unit, moq,
                        status, import_source)
  select a.id, pairs.n,
         case when exists (select 1 from categories c2 where c2.id = pairs.c)
              then pairs.c else null end,
         case when pairs.i = 1
           then 'Indicative price: a Kampala wholesale estimate, not quoted by the supplier. Ask for a quotation.'
           else 'Price as published in the source directory. Confirm before ordering.' end,
         pairs.p, pairs.u, 1, 'published', 'uganda-b2b'
  from pairs
  join accounts a on a.import_code = pairs.code
  where not exists (
    select 1 from products p2 where p2.supplier_id = a.id and p2.name = pairs.n
  )
  returning id, import_source
)
select count(*) as listings_created from ins;

-- Price basis, so a buyer can tell an estimate from a quotation.
insert into product_specs (product_id, key, value, sort)
select p.id, 'Price basis',
       case when p.description like 'Indicative%'
         then 'Indicative — market estimate, not quoted by the supplier'
         else 'As published in the source directory' end, 0
from products p
where p.import_source = 'uganda-b2b'
  and not exists (select 1 from product_specs s where s.product_id = p.id and s.key = 'Price basis');

commit;
